import pandas as pd


def run(inputs: dict) -> dict:
    df = inputs["payments"].copy()

    valid_currencies = {"USD", "EUR", "GBP"}

    def classify(row):
        amount = row["amount"]
        currency = row["currency"]
        country = row["country"]

        if pd.isna(amount):
            return "AMT_NULL"
        if amount <= 0:
            return "AMT_NONPOS"
        if pd.isna(currency) or currency not in valid_currencies:
            return "CCY_INVALID"
        if pd.isna(country):
            return "CTRY_NULL"
        return None

    reason_codes = df.apply(classify, axis=1)

    rejected_mask = reason_codes.notna()

    rejects = df[rejected_mask].copy()
    rejects["reason_code"] = reason_codes[rejected_mask]

    clean = df[~rejected_mask].copy()
    clean["amount"] = clean["amount"].round(2)

    return {
        "payments_clean": clean,
        "payments_rejects": rejects,
    }
